int Dsp::register_par(const ParamReg& reg)
{
	reg.registerFloatVar("klon_centaur.gain",N_("Gain"),"S","",&fHslider2, 0.35, 0.0, 1.0, 0.01, 0);
	reg.registerFloatVar("klon_centaur.level",N_("Level"),"S","",&fHslider0, 0.5, 0.0, 1.0, 0.01, 0);
	reg.registerFloatVar("klon_centaur.treble",N_("Treble"),"S","",&fHslider1, 0.5, 0.0, 1.0, 0.01, 0);
	return 0;
}

int Dsp::register_params_static(const ParamReg& reg)
{
	return static_cast<Dsp*>(reg.plugin)->register_par(reg);
}

PluginDef *plugin() {
	return new Dsp();
}

void Dsp::del_instance(PluginDef *p)
{
	delete static_cast<Dsp*>(p);
}

